window.MGProseData("5704fc78c7c6c5a4706abb25ac488e03b850e50b4b720af87e52729c94f466ce",{"html":"\u003ch2>S1 有限频带上的逆\u003c/h2>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_k(y)=e^{2\\pi i k\\cdot y}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_\\alpha(k)=\\alpha k_1+k_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。周期积分分部给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat{N_\\alpha u}(k)=2\\pi i\\,d_\\alpha(k)\\widehat u(k).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_\\alpha(k)=k_2\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_\\alpha(k)\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的逆为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT_{\\alpha,N}F=\\sum_{0\u0026lt;|k|\\le N}\n\\frac{\\widehat F(k)}{2\\pi i\\,d_\\alpha(k)}e_k.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n逐频率相乘可验证两个复合都是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的恒等算子。\u003c/p>\n\u003cp>对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 范数度量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\displaystyle\n\\|T_{\\alpha,N}\\|_{H^r\\to H^r}\n=\\frac{1}{2\\pi\\min_{0\u0026lt;|k|\\le N}|d_\\alpha(k)|}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n上界来自对每个加权傅里叶系数应用乘子的绝对值上界。频带有限且非空，取使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_\\alpha(k)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 最小的单频 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即得等号。\u003c/p>\n\u003ch2>S2 有算术界的截断误差\u003c/h2>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat u(0)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u(k)=\\frac{\\widehat F(k)}{2\\pi i\\,d_\\alpha(k)}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n假设给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widehat u(k)|\\le (2\\pi c)^{-1}\\langle k\\rangle^s|\\widehat F(k)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n光滑 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的系数快速衰减，因为对任意整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，周期积分分部给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">Δ\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(1+4\\pi^2|k|^2)^M|\\widehat F(k)|\n\\le \\|(1-\\Delta)^M F\\|_{L^1}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat u(k)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也快速衰减。二维格点和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_k\\langle k\\rangle^{-a}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u0026gt;2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时收敛，例如按二进环带计数可得。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的傅里叶级数及其各阶导数级数都绝对一致收敛，定义了光滑零均值函数。逐项求导给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，这里用到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是归一化环面 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的完备正交系。零均值解的唯一性由非零频率上的乘子均非零得到。\u003c/p>\n\u003cp>由 S1，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 正是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;|k|\\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的截断。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k|\u0026gt;N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k\\rangle^{-2q}\\le(1+N^2)^{-q}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\|u-u_N\\|_{H^r}^2\n\u0026amp;\\le (2\\pi c)^{-2}\n\\sum_{|k|\u0026gt;N}\\langle k\\rangle^{2(r+s)}|\\widehat F(k)|^2\\\\\n\u0026amp;\\le (2\\pi c)^{-2}(1+N^2)^{-q}\\|F\\|_{H^{r+s+q}}^2.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n开平方即得所求估计，对所有实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均成立。\u003c/p>\n\u003ch2>S3 固定频带内改变方向\u003c/h2>\n\u003cp>由 S1，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;|k|\\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003c/mrow>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmtext> \u003c/mtext>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat{u_\\alpha-u_\\beta}(k)\n=\\frac{(\\beta-\\alpha)k_1}{2\\pi i\\,d_\\alpha(k)d_\\beta(k)}\\,\\widehat F(k).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两个分母因子的绝对值都至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>δ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_1|\\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。乘以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 权重后平方求和，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\displaystyle\n\\|u_\\alpha-u_\\beta\\|_{H^r}\n\\le \\frac{|\\alpha-\\beta|N}{2\\pi\\delta^2}\\|F\\|_{H^r}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch2>S4 整体可逆性与全部允许损失\u003c/h2>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_s(\\alpha)=\\inf_{k\\in\\mathbb Z^2\\setminus\\{0\\}}\n\\langle k\\rangle^s|d_\\alpha(k)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n题设的 Sobolev 估计成立当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_s(\\alpha)\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。必要性只需对任一固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 代入 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u=e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，约去 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k\\rangle^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n1\\le 2\\pi C_{\\alpha,r,s}\\langle k\\rangle^s|d_\\alpha(k)|\n\\qquad(k\\ne0).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_s(\\alpha)\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由乘子公式逐频率平方求和即得估计。单频测试同时表明，对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，最优常数都是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(2\\pi A_s(\\alpha))^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>算子 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha:C^\\infty_0\\to C^\\infty_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总是单射，因为零均值消去了零频率，其余乘子均非零。若某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_s(\\alpha)\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 S2 以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c=A_s(\\alpha)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 适用，给出每个光滑零均值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的唯一光滑零均值解。若所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_s(\\alpha)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对每个整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可选互异频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_j\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>j\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\langle k_j\\rangle\\ge 2^j,\n\\qquad\n|d_\\alpha(k_j)|\u0026lt;\\langle k_j\\rangle^{-j}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_j(\\alpha)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且去掉有限多个正项后下确界仍为零。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF=\\sum_{j\\ge1}2\\pi i\\,d_\\alpha(k_j)e_{k_j}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n每个总阶为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的导数级数，其第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项一致范数至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(2\\pi)^{m+1}\\langle k_j\\rangle^{m-j}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\\ge m+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(2\\pi)^{m+1}2^{-j}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 控制。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 光滑且零均值。若有光滑解，乘子公式将强制 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat u(k_j)=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，与光滑函数的系数衰减矛盾。这证明了可逆性恰好等价于存在有限的允许损失。\u003c/p>\n\u003cp>\u003cstrong>连分数分类。\u003c/strong> 令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_n/q_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的简单连分数收敛分数，并定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">lim sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmi>log\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmi>log\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\tau=\\limsup_{n\\to\\infty}\\frac{\\log q_{n+1}}{\\log q_n}\\in[1,\\infty].\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n全部允许的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构成集合\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmtext> 且 \u003c/mtext>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msubsup>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mstyle>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmtext> 且 \u003c/mtext>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msubsup>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mstyle>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\begin{cases}\n\\varnothing,\u0026amp;\\tau=\\infty,\\\\[2pt]\n[\\tau,\\infty),\u0026amp;\n\\tau\u0026lt;\\infty\\ \\text{且}\\ \\displaystyle\\sup_{n\\ge1}\\frac{q_{n+1}}{q_n^\\tau}\u0026lt;\\infty,\\\\[6pt]\n(\\tau,\\infty),\u0026amp;\n\\tau\u0026lt;\\infty\\ \\text{且}\\ \\displaystyle\\sup_{n\\ge1}\\frac{q_{n+1}}{q_n^\\tau}=\\infty.\n\\end{cases}}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>为证明分类，记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(q)=\\min_{p\\in\\mathbb Z}|q\\alpha-p|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为整数。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q=|k_1|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_\\alpha(k)|\\ge\\rho(q)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k\\rangle\\ge q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_\\alpha(k)|\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反向对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 取距离 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 最近的整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|p|\\le|\\alpha|q+1/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle(q,-p)\\rangle\\le K_\\alpha q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K_\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关。故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo>⟺\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_s(\\alpha)\u0026gt;0\n\\quad\\Longleftrightarrow\\quad\n\\inf_{q\\ge1}q^s\\rho(q)\u0026gt;0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理，其简单连分数无限。设部分商为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_0=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_{n+1}=a_{n+1}q_n+q_{n-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，分母从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 起严格递增。收敛分数的递推给出相邻整数向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(p_n,q_n),(p_{n+1},q_{n+1})\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的行列式绝对值为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将完全商 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_{n+1}=[a_{n+1};a_{n+2},\\ldots]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 代回连分数，利用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_{n+1}\u0026lt;x_{n+1}\u0026lt;a_{n+1}+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_n\\alpha-p_n=\\frac{(-1)^n}{q_nx_{n+1}+q_{n-1}},\n\\qquad\n\\frac1{q_{n+1}+q_n}\u0026lt;|q_n\\alpha-p_n|\u0026lt;\\frac1{q_{n+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;q\u0026lt;q_{n+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，把任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(p,q)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 写成上述相邻向量的整数线性组合，系数记为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>A\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|q\\alpha-p|=|A|\\,|q_n\\alpha-p_n|\\ge |q_n\\alpha-p_n|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，分母范围迫使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都非零且异号。相邻收敛分数的误差也异号，所以相乘后的两个误差项同号，仍有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|q\\alpha-p|\\ge|q_n\\alpha-p_n|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>因此当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_n\\le q\u0026lt;q_{n+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msubsup>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq^s\\rho(q)\\ge \\frac{q_n^s}{2q_{n+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(q_n)\\le |q_n\\alpha-p_n|\u0026lt;1/q_{n+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。有限个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u0026lt;q_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(q)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均为正，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo>⟺\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msubsup>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\inf_{q\\ge1}q^s\\rho(q)\u0026gt;0\n\\quad\\Longleftrightarrow\\quad\n\\sup_{n\\ge1}\\frac{q_{n+1}}{q_n^s}\u0026lt;\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026gt;\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsup>\u003cmi>s\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\u0026lt;s\u0026#x27;\u0026lt;s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则充分大的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmsup>\u003cmi>s\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_{n+1}\\le q_n^{s\u0026#x27;}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以上确界有限。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsup>\u003cmi>s\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;s\u0026#x27;\u0026lt;\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则无穷多个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmsup>\u003cmi>s\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_{n+1}\u0026gt;q_n^{s\u0026#x27;}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，相应比值无界。有限端点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s=\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 由上确界条件判定。\u003c/p>\n\u003cp>所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可逆恰好当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为\u003cstrong>非 Liouville 无理数\u003c/strong>。具体而言，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu(\\alpha)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>ν\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha-p/q|\u0026lt;q^{-\\nu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对任意大分母 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立的指数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ν\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的上确界，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu(\\alpha)=1+\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ν\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nu\u0026lt;1+\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，沿无穷多个满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>ν\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_{n+1}\u0026gt;q_n^{\\nu-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的收敛分数，上述误差上界给出所需逼近。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ν\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nu\u0026gt;1+\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ν\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\u0026lt;s\u0026lt;\\nu-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\inf_q q^s\\rho(q)\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026gt;\u003c/mo>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>ν\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha-p/q|\\ge c q^{-s-1}\u0026gt;q^{-\\nu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对充分大的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立。这也说明临界损失是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu(\\alpha)-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其取到与否由上面的端点条件决定。\u003c/p>\n\u003cp>\u003cstrong>方向 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*=\\sqrt2-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/strong> 对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nd_{\\alpha_*}(k)\\bigl(k_2-(1+\\sqrt2)k_1\\bigr)\n=(k_2-k_1)^2-2k_1^2\\in\\mathbb Z\\setminus\\{0\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右边非零由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sqrt2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理得到。第二个因子的绝对值至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D|k|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/msqrt>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D=\\sqrt{1+(1+\\sqrt2)^2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_{\\alpha_*}(k)|\\ge D^{-1}\\langle k\\rangle^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 允许，而分类中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 排除了所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。允许损失恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[1,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，最小值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> \u003cstrong>取到\u003c/strong>。\u003c/p>\n\u003cp>所问的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 估计也成立。令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=m+4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选择坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_j|\\ge |k|/\\sqrt2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，沿该坐标积分分部 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 次，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>t\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widehat F(k)|\\le\n\\left(\\frac{\\sqrt2}{2\\pi}\\right)^t |k|^{-t}\\|F\\|_{C^t}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由刚证明的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_{\\alpha_*}(k)|\\ge(D|k|)^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，逆乘子的绝对值至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D|k|/(2\\pi)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对解求任意总阶不超过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的导数，逐项估计后得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|N_{\\alpha_*}^{-1}F\\|_{C^m}\n\\le\n\\frac{D(2\\pi)^m}{2\\pi}\n\\left(\\frac{\\sqrt2}{2\\pi}\\right)^{m+4}\n\\left(\\sum_{k\\ne0}|k|^{-3}\\right)\\|F\\|_{C^{m+4}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n二维格点和收敛，故右侧给出了与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关的有限常数。\u003c/p>\n\u003ch2>S5 邻近方向的一致估计\u003c/h2>\n\u003cp>不存在这样的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J,s,C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。任取包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的开区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选有理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p/q\\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>p\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmi>j\u003c/mi>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\alpha_j=\\frac pq+\\frac{\\alpha_*}{j},\\qquad\nk=(q,-p),\\qquad u=e_k.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都无理，且充分大的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_j\\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。固定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 光滑、零均值且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u\\|_{L^2}=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意固定有限 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>q\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmo>⟶\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|N_{\\alpha_j}u\\|_{H^s}\n=2\\pi q\\,|\\alpha_j-p/q|\\,\\langle k\\rangle^s\\longrightarrow0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此任何固定有限 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都无法使所要求的不等式对这些方向成立。\u003c/p>\n\u003ch2>S6 一个具体方向的不可解数据\u003c/h2>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_n=10^{n!},\\qquad\np_n=\\sum_{j=1}^{n}10^{n!-j!},\\qquad\nd_n=q_n\\alpha-p_n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n阶乘指数严格递增，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>9\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;\\alpha\\le\\sum_{\\ell\\ge1}10^{-\\ell}=1/9\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;p_n\u0026lt;q_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。尾项满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmtext> \u003c/mtext>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n0\u0026lt;d_n\n=q_n\\sum_{j\u0026gt;n}10^{-j!}\n\\le \\frac{10}{9}\\,q_n\\,10^{-(n+1)!}\n=\\frac{10}{9}\\,q_n^{-n}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha=a/b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">bd_n=aq_n-bp_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是正整数，但 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">bd_n\\to0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，矛盾。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理。\u003c/p>\n\u003cp>取互异频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_n=(q_n,-p_n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，构造同一个数据\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\displaystyle\nF(y)=\\sum_{n=1}^{\\infty} 2\\pi i\\,d_n\\,e^{2\\pi i(q_n y_1-p_n y_2)}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n总阶为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任意导数，其第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项的一致范数至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{10}{9}(2\\pi)^{m+1}q_n^{m-n}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\ge m+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_n^{m-n}\\le q_n^{-1}\\le10^{-n}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以所有导数级数都绝对一致收敛，且逐项积分给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的均值为零。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有光滑零均值解，则在每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_\\alpha(k_n)=d_n\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2\\pi i\\,d_n\\,\\widehat u(k_n)=2\\pi i\\,d_n,\n\\qquad \\widehat u(k_n)=1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_n|\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，这与光滑函数的傅里叶系数衰减矛盾。因此该 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 没有光滑零均值解。\u003c/p>\n","source":"assets/content/5704fc78c7c6c5a4706abb25ac488e03b850e50b4b720af87e52729c94f466ce.html"});
